\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Warm Advocacy Color Theme ──
\definecolor{primary}{HTML}{1A1512}      % deep charcoal-brown (dark background)
\definecolor{secondary}{HTML}{C45E30}      % rich rust orange
\definecolor{accent}{HTML}{F4A100}        % warm gold
\definecolor{accentred}{HTML}{B91C1C}     % warm red
\definecolor{bgposter}{HTML}{1A1512}       % poster background (dark)
\definecolor{redbg}{HTML}{2D1F1A}         % card tint backgrounds (dark warm)
\definecolor{bluebg}{HTML}{2D241A}
\definecolor{darkbg}{HTML}{2D1F1A}
\definecolor{statbg}{HTML}{3D2A1F}        % stat callout background
\definecolor{textlight}{HTML}{FFFFFF}     % white text on dark
\definecolor{textwarm}{HTML}{F5E8E2}      % warm off-white
\definecolor{textgold}{HTML}{F4A100}      % gold accent text

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=4pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textwarm}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  orangecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=statbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.25},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=statbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.25},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{accentred},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentred},
    coltitle=accentred, colbacktitle=statbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accentred!50},
    valign=top, drop shadow={opacity=0.25},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!30!black,
    borderline west={8pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=secondary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{78}{94}\selectfont\bfseries\color{textlight} HUNGER DOESN'T WAIT}\\[10pt]
  {\fontsize{60}{72}\selectfont\bfseries\color{accent} Together We Can End It}\\[14pt]
  {\fontsize{28}{36}\selectfont\color{textwarm} 48 Million Americans Face Hunger. But There's Hope.}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{secondary!40},
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.28\linewidth}\centering
    \fcolorbox{accentred!50}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{accent} 48M}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textlight} People Facing Hunger}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textwarm!70} in America}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.28\linewidth}\centering
    \fcolorbox{accent!50}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{accent} 5.7B}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textlight} Meals Provided}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textwarm!70} Through The Network}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.28\linewidth}\centering
    \fcolorbox{secondary!50}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{secondary} 14M}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textlight} Children Affected}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textwarm!70} Face Hunger in U.S.}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ CRISIS SECTION ══
\posterbox[redcard, title={The Hunger Crisis}
]{name=crisis, column=1, between=row7 and row11}{
  \fontsize{32}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Hunger is not distant — it's in every community across America
    \item 48 million people face food insecurity
    \item 14 million children cannot count on their next meal
    \item Families in urban and rural areas struggle daily
  \end{itemize}
}

% ══ IMPACT SECTION ══
\posterbox[orangecard, title={Our Collective Impact}
]{name=impact, column=2, between=row7 and row11}{
  \fontsize{32}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{5.7 billion meals} distributed nationwide
    \item \textbf{4.3 billion lbs} of food rescued from waste
    \item \textbf{60,000+ programs} distributing free food
    \item \textbf{200+ food banks} in the network
  \end{itemize}
}

% ══ FOUR PILLARS ══
\posterbox[goldcard, title={How We Unite Communities}
]{name=pillars, column=3, between=row7 and row11}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Research-Driven} — Listening to those facing hunger
    \item \textbf{Local Wisdom} — Community leaders driving national action
    \item \textbf{Nationwide Scale} — Fast, reliable food delivery
    \item \textbf{Nutrition Focus} — Making healthy food accessible
  \end{itemize}
}

% ══ $1 = 10 MEALS CONVERSION ══
\posterbox[
  enhanced, colback=accent, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=conversion, column=1, span=3, between=row11 and row13}{
  {\fontsize{72}{86}\selectfont\bfseries\color{primary} \$1 = 10 MEALS}\\[8pt]
  {\fontsize{28}{36}\selectfont\color{primary} Every dollar provides at least 10 meals to neighbors in need}
}

% ══ CALLS TO ACTION ══
\posterbox[highlightcard, title={Make a Difference}
]{name=action1, column=1, between=row13 and row16}{
  \fontsize{34}{42}\selectfont\bfseries\color{textlight}
  \textbf{DONATE}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{textwarm}
  Every \$1 provides 10 meals. Your gift is matched to move fresh food fast.}
}

\posterbox[highlightcard, title={}
]{name=action2, column=2, between=row13 and row16}{
  \fontsize{34}{42}\selectfont\bfseries\color{textlight}
  \textbf{ADVOCATE}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{textwarm}
  Urge lawmakers to support community programs helping neighbors.}
}

\posterbox[highlightcard, title={}
]{name=action3, column=3, between=row13 and row16}{
  \fontsize{34}{42}\selectfont\bfseries\color{textlight}
  \textbf{FUNDRAISE}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{textwarm}
  Inspire your community to come together and make a difference.}
}

% ══ VOLUNTEER + VISION ══
\posterbox[redcard, title={Volunteer}
]{name=volunteer, column=1, span=3, between=row16 and row18}{
  \fontsize{34}{42}\selectfont
  \begin{center}
  \textbf{\color{accentred} SORTING, PACKING \& DISTRIBUTING FOOD TAKES MANY HANDS — INCLUDING YOURS}\\[6pt]
  {\fontsize{26}{32}\selectfont\color{textwarm} Join thousands of volunteers nationwide making a tangible difference}
  \end{center}
}

% ══ FOOTER ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwarm,
  arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=8pt, bottom=8pt,
  halign=center, valign=center
]{name=footer, column=1, span=3, between=row18 and bottom}{
  {\fontsize{26}{32}\selectfont\color{textwarm} Together, we can end hunger in America. \textbf{\color{accent} The resolve is stronger than ever.}}
}

\end{tcbposter}
\end{document}

